import{_ as s}from"./chunks/workspace-icon.DEyVtlmw.js";import{_ as l,C as n,o as i,c as g,a6 as d,E as o,j as e,a}from"./chunks/framework.CrjICMdL.js";const h="/rb_cobot_docs_muscat/images/move-menu/workspace-where.avif",c="/rb_cobot_docs_muscat/images/move-menu/workspace-panel.avif",m="/rb_cobot_docs_muscat/images/move-menu/workspace-example-create.avif",p="/rb_cobot_docs_muscat/images/move-menu/workspace-example-edit.avif",b="/rb_cobot_docs_muscat/images/move-menu/workspace-example-load.avif",S=JSON.parse('{"title":"워크스페이스","description":"","frontmatter":{"title":"워크스페이스"},"headers":[],"relativePath":"manual/move-menu/workspace.md","filePath":"manual/move-menu/workspace.md","lastUpdated":1792552919000}'),_={name:"manual/move-menu/workspace.md"};function u(x,t,k,f,y,P){const r=n("DemoFrame");return i(),g("div",null,[t[0]||(t[0]=d('<h1 id="워크스페이스" tabindex="-1">워크스페이스 <a class="header-anchor" href="#워크스페이스" aria-label="Permalink to &quot;워크스페이스&quot;">​</a></h1><p><img src="'+s+'" alt="워크스페이스 아이콘"> 동작 화면의 3D 장면에 놓을 오브젝트(도형·파일)를 구성하고 저장하는 메뉴입니다.</p><p>화면에서 파란 테두리로 표시한 곳입니다. 오른쪽 메뉴의 항목을 누르면 옆에 이 패널이 열립니다.</p><p><img src="'+h+'" alt="워크스페이스 위치"></p><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>실습은 작업별로 나뉘어 있고 서로 이어지지 않습니다. 필요한 것을 골라 바로 시작할 수 있으며, 각 실습은 <strong>소개 → 직접 해 보기</strong> 순서로 진행합니다. 소개 단계에서는 설명을 확인하고, 직접 해 보기 단계에서 안내된 부분을 조작하세요. <strong>다시 하기</strong>를 누르면 해당 실습이 처음 상태로 초기화됩니다.</p><table tabindex="0"><thead><tr><th>실습</th><th>시작 상태</th><th>하는 일</th></tr></thead><tbody><tr><td>새로 만들기</td><td>워크스페이스가 없음</td><td>이름을 입력해 빈 워크스페이스 만들기</td></tr><tr><td>도형 추가</td><td><code>Welding cell</code>이 열려 있음</td><td>직육면체 추가하기</td></tr><tr><td>위치·크기 바꾸기</td><td><code>Welding cell</code>이 열려 있음</td><td>도형의 X 위치와 SX 크기 바꾸기</td></tr><tr><td>목록 관리</td><td><code>Welding cell</code>이 열려 있음</td><td>도형 숨기기와 다시 표시</td></tr><tr><td>저장·불러오기</td><td><code>Welding cell</code>이 열려 있음</td><td>위치를 바꾸고 저장한 뒤 닫았다가 다시 불러오기</td></tr><tr><td>자유 실습</td><td><code>Welding cell</code>이 열려 있음</td><td>배운 기능을 자유롭게 사용</td></tr></tbody></table><h3 id="새로-만들기" tabindex="-1">새로 만들기 <a class="header-anchor" href="#새로-만들기" aria-label="Permalink to &quot;새로 만들기&quot;">​</a></h3>',8)),o(r,{id:"move-menu-workspace-create"}),t[1]||(t[1]=e("h3",{id:"도형-추가",tabindex:"-1"},[a("도형 추가 "),e("a",{class:"header-anchor",href:"#도형-추가","aria-label":'Permalink to "도형 추가"'},"​")],-1)),o(r,{id:"move-menu-workspace-add"}),t[2]||(t[2]=e("h3",{id:"위치·크기-바꾸기",tabindex:"-1"},[a("위치·크기 바꾸기 "),e("a",{class:"header-anchor",href:"#위치·크기-바꾸기","aria-label":'Permalink to "위치·크기 바꾸기"'},"​")],-1)),o(r,{id:"move-menu-workspace-edit"}),t[3]||(t[3]=e("h3",{id:"목록-관리",tabindex:"-1"},[a("목록 관리 "),e("a",{class:"header-anchor",href:"#목록-관리","aria-label":'Permalink to "목록 관리"'},"​")],-1)),o(r,{id:"move-menu-workspace-manage"}),t[4]||(t[4]=e("h3",{id:"저장·불러오기",tabindex:"-1"},[a("저장·불러오기 "),e("a",{class:"header-anchor",href:"#저장·불러오기","aria-label":'Permalink to "저장·불러오기"'},"​")],-1)),o(r,{id:"move-menu-workspace-save"}),t[5]||(t[5]=e("h3",{id:"자유-실습",tabindex:"-1"},[a("자유 실습 "),e("a",{class:"header-anchor",href:"#자유-실습","aria-label":'Permalink to "자유 실습"'},"​")],-1)),o(r,{id:"move-menu-workspace-free"}),t[6]||(t[6]=d('<h2 id="패널-화면" tabindex="-1">패널 화면 <a class="header-anchor" href="#패널-화면" aria-label="Permalink to &quot;패널 화면&quot;">​</a></h2><p><img src="'+c+'" alt="워크스페이스 패널"></p><p>위 화면은 가상 로봇(데모)에서 캡처한 것이라 값은 실제 로봇과 다를 수 있습니다.</p><p>처음에는 <strong>새로 만들기</strong>와 <strong>불러오기</strong> 두 버튼만 보입니다. 패널 위쪽에는 <strong>베이스</strong>·<strong>툴</strong> 탭이 있고, 툴이 여러 개인 로봇에서는 탭 이름이 오른쪽 툴·왼쪽 툴·툴 N처럼 나뉩니다.</p><h2 id="워크스페이스-열기" tabindex="-1">워크스페이스 열기 <a class="header-anchor" href="#워크스페이스-열기" aria-label="Permalink to &quot;워크스페이스 열기&quot;">​</a></h2><ul><li><strong>새로 만들기</strong>: 이름을 입력해 새 워크스페이스를 만듭니다(&quot;새 워크스페이스 만들기&quot; 창).</li><li><strong>불러오기</strong>: 저장된 워크스페이스를 고릅니다. 저장하지 않은 변경 사항이 있는 상태에서 다른 워크스페이스를 열면 변경 사항이 사라진다는 확인 창이 뜹니다.</li></ul><h2 id="워크스페이스를-연-뒤" tabindex="-1">워크스페이스를 연 뒤 <a class="header-anchor" href="#워크스페이스를-연-뒤" aria-label="Permalink to &quot;워크스페이스를 연 뒤&quot;">​</a></h2><p>버튼 위치와 상태 표시, 목록 선택 모드, 속성 입력, 3D 편집 도구는 <a href="./workspace-editor">편집 화면 구성</a>에서 번호가 있는 화면과 함께 설명합니다.</p><table tabindex="0"><thead><tr><th>영역</th><th>설명</th></tr></thead><tbody><tr><td>이름·저장 상태</td><td>워크스페이스 이름과 <strong>저장됨</strong> / <strong>저장 안 됨</strong> 표시. 이름은 바꿀 수 있습니다.</td></tr><tr><td>되돌리기 · 다시 실행</td><td>편집 내용을 되돌리거나 다시 적용합니다.</td></tr><tr><td><strong>워크스페이스 메뉴</strong></td><td>새로 만들기, 불러오기, 이름 변경, 사본 만들기, 삭제, 오브젝트 전체 삭제, 마지막 저장 상태로 되돌리기</td></tr><tr><td><strong>오브젝트 추가</strong></td><td><strong>직육면체</strong>, <strong>원기둥</strong>, <strong>구</strong>, <strong>불러온 파일</strong>을 더합니다.</td></tr><tr><td><strong>오브젝트 리스트</strong></td><td>추가한 오브젝트 목록. 항목별로 씬에서 숨기기/다시 표시, 삭제를 하고, <strong>선택</strong> 모드에서 여러 개를 한꺼번에 숨기거나 삭제합니다.</td></tr><tr><td><strong>오브젝트 속성</strong></td><td>선택한 오브젝트의 <strong>위치</strong>·<strong>회전</strong>·<strong>크기</strong>를 수치로 입력하고 <strong>초기화</strong>로 되돌립니다. 3D 편집 도구는 오브젝트 하나를 선택했을 때 3D 화면 왼쪽에 나타납니다.</td></tr></tbody></table><h2 id="제한과-안내" tabindex="-1">제한과 안내 <a class="header-anchor" href="#제한과-안내" aria-label="Permalink to &quot;제한과 안내&quot;">​</a></h2><ul><li>도형은 <strong>최대 5개</strong>까지 추가할 수 있습니다.</li><li>불러온 파일은 워크스페이스에 <strong>1개만</strong> 둘 수 있습니다. 새 파일을 넣으면 기존 파일을 교체할지 묻습니다.</li><li>STEP 형식(.stp, .step) 파일은 불러오는 데 시간이 오래 걸릴 수 있다는 안내가 표시됩니다.</li><li>이름에는 공백이나 <code>#</code> <code>?</code> <code>&amp;</code> <code>%</code> 문자를 쓸 수 없습니다.</li><li>저장하지 않은 변경 사항이 있는 채로 닫으면 <strong>저장하지 않고 닫기</strong>를 묻습니다.</li></ul><h2 id="예제-작업대와-원기둥-만들기" tabindex="-1">예제: 작업대와 원기둥 만들기 <a class="header-anchor" href="#예제-작업대와-원기둥-만들기" aria-label="Permalink to &quot;예제: 작업대와 원기둥 만들기&quot;">​</a></h2><p><strong>베이스</strong> 탭의 <code>demo_cell</code> 워크스페이스에 작업대와 원기둥을 배치하는 예제입니다. <strong>새로 만들기</strong> 실습에서 <code>demo_cell</code>을 만든 뒤 이어서 따라 해 볼 수 있습니다. <strong>자유 실습</strong>은 <code>Welding cell</code>이 열려 있는 상태로 시작하므로, 1번에서 새로 만들거나 열려 있는 워크스페이스에 도형을 더하며 연습하세요.</p><h3 id="_1-빈-워크스페이스-만들기" tabindex="-1">1. 빈 워크스페이스 만들기 <a class="header-anchor" href="#_1-빈-워크스페이스-만들기" aria-label="Permalink to &quot;1. 빈 워크스페이스 만들기&quot;">​</a></h3><ol><li><strong>새로 만들기</strong>를 누릅니다. 이미 다른 워크스페이스를 편집 중이라면 상단 <strong>워크스페이스 메뉴</strong>에서 <strong>새로 만들기</strong>를 선택합니다.</li><li>이름에 <code>demo_cell</code>을 입력하고 <strong>확인</strong>을 누릅니다.</li><li>상단 이름이 <code>demo_cell</code>인지 확인합니다. 새 워크스페이스에는 직접 사용할 도형을 추가합니다.</li></ol><p><code>demo_cell</code>이 이미 열려 있다면 이 단계는 건너뜁니다. 다른 워크스페이스를 새로 만들 때는 기존 이름과 구분되는 이름을 입력하세요.</p><p><img src="'+m+'" alt="demo_cell 워크스페이스 이름 입력"></p><h3 id="_2-직육면체로-작업대-추가하기" tabindex="-1">2. 직육면체로 작업대 추가하기 <a class="header-anchor" href="#_2-직육면체로-작업대-추가하기" aria-label="Permalink to &quot;2. 직육면체로 작업대 추가하기&quot;">​</a></h3><p>이미 추가한 직육면체가 있다면 그 항목을 선택하고 3번부터 진행합니다.</p><ol><li><strong>오브젝트 리스트</strong> 오른쪽 **+ (오브젝트 추가)**를 누릅니다.</li><li><strong>직육면체</strong>를 누릅니다. 목록에 새 항목이 추가됩니다.</li><li>목록의 도형을 선택하고 아래 <strong>오브젝트 속성</strong>의 입력칸을 눌러 다음 값을 입력합니다. 키보드로 입력한 뒤 Enter를 누르세요. 화면 숫자 키패드를 사용한다면 <strong>Set</strong>으로 적용합니다.</li></ol><table tabindex="0"><thead><tr><th>속성</th><th style="text-align:right;">X / RX / SX</th><th style="text-align:right;">Y / RY / SY</th><th style="text-align:right;">Z / RZ / SZ</th></tr></thead><tbody><tr><td>위치 (mm)</td><td style="text-align:right;">500</td><td style="text-align:right;">0</td><td style="text-align:right;">150</td></tr><tr><td>회전 (°)</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td></tr><tr><td>크기 (mm)</td><td style="text-align:right;">300</td><td style="text-align:right;">300</td><td style="text-align:right;">300</td></tr></tbody></table><ol start="4"><li>항목 오른쪽 **⋮ (오브젝트 메뉴)**에서 <strong>이름 변경</strong>을 선택합니다. <code>Worktable</code>을 입력하고 Enter를 누릅니다.</li><li>3D 화면에서 작업대가 보이는지 확인합니다. 드래그로 시점을 돌리고 마우스 휠로 확대·축소할 수 있습니다.</li></ol><p><strong>위치·크기는 mm, 회전은 ° 단위</strong>입니다. 크기 SX·SY·SZ에는 배율이 아니라 원하는 치수를 입력합니다. 이 예제의 수치는 실습용 배치입니다.</p><p><img src="'+p+'" alt="Worktable 도형의 위치와 크기 편집 예제"></p><h3 id="_3-원기둥-추가하고-개별-편집하기" tabindex="-1">3. 원기둥 추가하고 개별 편집하기 <a class="header-anchor" href="#_3-원기둥-추가하고-개별-편집하기" aria-label="Permalink to &quot;3. 원기둥 추가하고 개별 편집하기&quot;">​</a></h3><ol><li>다시 <strong>+ → 원기둥</strong>을 선택합니다.</li><li>추가된 원기둥을 선택하고 다음 값을 입력합니다.</li></ol><table tabindex="0"><thead><tr><th>속성</th><th style="text-align:right;">X / RX / SX</th><th style="text-align:right;">Y / RY / SY</th><th style="text-align:right;">Z / RZ / SZ</th></tr></thead><tbody><tr><td>위치 (mm)</td><td style="text-align:right;">500</td><td style="text-align:right;">300</td><td style="text-align:right;">100</td></tr><tr><td>회전 (°)</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td></tr><tr><td>크기 (mm)</td><td style="text-align:right;">100</td><td style="text-align:right;">100</td><td style="text-align:right;">200</td></tr></tbody></table><ol start="3"><li>이름을 <code>Post</code>로 바꿉니다. 목록에서 <code>Worktable</code>과 <code>Post</code>를 번갈아 선택해 각 도형의 속성을 확인합니다.</li></ol><p>속성의 <strong>초기화</strong>는 선택한 도형의 위치·회전을 0으로, 크기를 기본 치수로 되돌립니다. 워크스페이스 전체를 지우는 기능과는 다릅니다.</p><h3 id="_4-숨기기·삭제·되돌리기-연습하기" tabindex="-1">4. 숨기기·삭제·되돌리기 연습하기 <a class="header-anchor" href="#_4-숨기기·삭제·되돌리기-연습하기" aria-label="Permalink to &quot;4. 숨기기·삭제·되돌리기 연습하기&quot;">​</a></h3><table tabindex="0"><thead><tr><th>해볼 작업</th><th>조작</th><th>확인할 결과</th></tr></thead><tbody><tr><td>잠깐 숨기기</td><td><code>Post</code>의 <strong>⋮ → 씬에서 숨기기</strong></td><td>목록에는 남고 3D 화면에서 숨겨집니다.</td></tr><tr><td>다시 표시하기</td><td>같은 항목의 <strong>⋮ → 씬에 다시 표시</strong></td><td>숨긴 도형이 다시 보입니다.</td></tr><tr><td>도형 하나 삭제하기</td><td><code>Post</code>의 <strong>⋮ → 오브젝트 삭제</strong></td><td>목록과 3D 화면에서 제거됩니다.</td></tr><tr><td>삭제 취소하기</td><td>패널 상단 <strong>되돌리기</strong></td><td>삭제한 도형이 돌아옵니다.</td></tr><tr><td>삭제 다시 적용하기</td><td>패널 상단 <strong>다시 실행</strong></td><td>취소했던 삭제가 다시 적용됩니다.</td></tr><tr><td>여러 항목 관리하기</td><td><strong>선택</strong>을 누르고 항목을 체크</td><td>선택한 항목들을 함께 숨기거나 삭제할 수 있습니다. <strong>선택 취소</strong>로 종료합니다.</td></tr></tbody></table><p>예제를 계속하려면 <strong>되돌리기</strong>로 작업대와 원기둥이 모두 남아 있는 상태로 만드세요. 되돌리기·다시 실행으로 고른 최종 상태는 <strong>저장</strong>을 눌러 저장하세요.</p><h3 id="_5-저장하고-다시-열기" tabindex="-1">5. 저장하고 다시 열기 <a class="header-anchor" href="#_5-저장하고-다시-열기" aria-label="Permalink to &quot;5. 저장하고 다시 열기&quot;">​</a></h3><ol><li>상단 <strong>저장</strong>을 누릅니다. 자동저장이 먼저 끝났다면 저장 버튼은 비활성화되어 있을 수 있습니다.</li><li>저장 직후의 <strong>저장됨</strong> 표시를 확인합니다. 이 표시는 잠시 후 사라집니다. <strong>저장 안 됨</strong>이 남아 있다면 변경 사항을 다시 확인합니다.</li><li><strong>닫기 → 불러오기</strong>를 누릅니다.</li><li>목록에서 <code>demo_cell</code>을 선택하고 <strong>확인</strong>을 누릅니다. 항목을 더블클릭해 바로 열 수도 있습니다. <code>Worktable</code>과 <code>Post</code>의 위치·크기가 유지되는지 확인합니다.</li></ol><p><img src="'+b+'" alt="저장한 demo_cell 워크스페이스 불러오기"></p><p>편집 내용은 자동으로 저장되며 <strong>저장</strong> 버튼으로 즉시 저장할 수도 있습니다. 이 페이지의 실습 데이터는 실습을 다시 시작하거나 새로 열면 초기화됩니다.</p><h2 id="워크스페이스-전체-관리" tabindex="-1">워크스페이스 전체 관리 <a class="header-anchor" href="#워크스페이스-전체-관리" aria-label="Permalink to &quot;워크스페이스 전체 관리&quot;">​</a></h2><p>패널 상단 <strong>워크스페이스 메뉴</strong>에서 이름 변경·사본 만들기·전체 삭제 등을 수행합니다. 메뉴별 동작과 비활성화 조건은 <a href="./workspace-editor#워크스페이스-메뉴-⑦">편집 화면 구성의 워크스페이스 메뉴</a>를 참고하세요.</p><p>이 실습에서는 <strong>직육면체·원기둥·구</strong>를 사용합니다. <strong>불러온 파일</strong>을 통한 파일 업로드는 실습에서 지원하지 않습니다.</p>',39))])}const w=l(_,[["render",u]]);export{S as __pageData,w as default};
